ALTER TABLE users MODIFY cpf CHAR(11) NULL, MODIFY phone VARCHAR(30) NULL, MODIFY address VARCHAR(500) NULL,
 ADD last_active_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), ADD inactivity_warned_at TIMESTAMP(6) NULL;
ALTER TABLE contacts MODIFY phone VARCHAR(30) NULL;
ALTER TABLE outbox ADD category VARCHAR(16) NOT NULL DEFAULT 'SERVICE', ADD created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6), ADD completed_at TIMESTAMP(6) NULL;
ALTER TABLE properties ADD entry_reason VARCHAR(500) NULL, ADD entry_recipient VARCHAR(200) NULL, ADD entry_until DATE NULL;
CREATE TABLE legal_acceptances(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,version VARCHAR(40) NOT NULL,document_hash CHAR(64) NOT NULL,accepted_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),expires_at TIMESTAMP(6) NULL, UNIQUE(user_id,version), FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE marketing_preferences(user_id BIGINT PRIMARY KEY,allowed BOOLEAN NOT NULL DEFAULT FALSE,updated_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),unsubscribe_hash CHAR(64) NOT NULL UNIQUE, FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE marketing_events(id BIGINT PRIMARY KEY AUTO_INCREMENT,user_id BIGINT NOT NULL,allowed BOOLEAN NOT NULL,version VARCHAR(40) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE privacy_tokens(token_hash CHAR(64) PRIMARY KEY,email VARCHAR(254) NOT NULL,expires_at TIMESTAMP(6) NOT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE privacy_requests(id BIGINT PRIMARY KEY AUTO_INCREMENT,email VARCHAR(254) NULL,user_id BIGINT NULL,kind VARCHAR(20) NOT NULL,status VARCHAR(20) NOT NULL DEFAULT 'OPEN',response TEXT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),due_at TIMESTAMP(6) NOT NULL,completed_at TIMESTAMP(6) NULL);
CREATE TABLE visit_identity(visit_id BIGINT PRIMARY KEY,ciphertext VARCHAR(500) NOT NULL,expires_at TIMESTAMP(6) NOT NULL,FOREIGN KEY(visit_id) REFERENCES visits(id) ON DELETE CASCADE);
CREATE TABLE privacy_rate_limits(bucket CHAR(64) PRIMARY KEY,attempts INT NOT NULL,expires_at TIMESTAMP(6) NOT NULL);
CREATE TABLE incident_holidays(day DATE PRIMARY KEY,name VARCHAR(150) NOT NULL);
CREATE TABLE privacy_incidents(id BIGINT PRIMARY KEY AUTO_INCREMENT,known_at TIMESTAMP(6) NOT NULL,due_at TIMESTAMP(6) NOT NULL,description TEXT NOT NULL,risk TEXT NOT NULL,owner VARCHAR(120) NOT NULL,containment TEXT NOT NULL,reportable BOOLEAN NOT NULL,anpd_protocol VARCHAR(250) NULL,holders_notice TEXT NULL,created_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6));
CREATE TABLE privacy_retention_runs(id BIGINT PRIMARY KEY AUTO_INCREMENT,executed_at TIMESTAMP(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),summary VARCHAR(500) NOT NULL);
ALTER TABLE visits MODIFY client_id BIGINT NULL;
INSERT INTO incident_holidays(day,name) SELECT day,name FROM holidays;
